                                                                                                                                                                                                             
  CREATE TABLE "TENANT_EVENT_FOLLOW_USERS"                                                                                                                                                        
   (	"EVENT_FOLLOW_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                  
	"CREATION_DATE" DATE DEFAULT SYSDATE NOT NULL ENABLE,                                                                                                                                                       
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                  
	"UPDATE_DATE" DATE DEFAULT SYSDATE NOT NULL ENABLE,                                                                                                                                                         
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                         
	"REMARK" NVARCHAR2(600),                                                                                                                                                                                    
	"EVENT_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                    
	"EXT_USER_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                 
	"EXT_ORG_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                  
	"STATUS" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                                     
	"FIRST_OPERATING_TIME" DATE,                                                                                                                                                                                
	"END_TIME" DATE,                                                                                                                                                                                            
	"EVENT_CAUSE" NVARCHAR2(1500),                                                                                                                                                                              
	"EVENT_SOLUTION_SCHEME" NVARCHAR2(1500),                                                                                                                                                                    
	"SOURCE_ASSISTANCE" NVARCHAR2(50),                                                                                                                                                                          
	"TRANSFER_EXT_USER_ID" NUMBER(20,0),                                                                                                                                                                        
	"REASON" NVARCHAR2(1024),                                                                                                                                                                                   
	"IS_FINAL_HANDLER" NUMBER DEFAULT 0,                                                                                                                                                                        
	"USER_IDENTITY" NVARCHAR2(20) DEFAULT 'SECONDARY' NOT NULL ENABLE,                                                                                                                                          
	"END_TYPE" NVARCHAR2(50),                                                                                                                                                                                   
	"RECEIVE_TIME" DATE DEFAULT SYSDATE NOT NULL ENABLE,                                                                                                                                                        
	"EVENT_SOLUTION_IMAGE" NVARCHAR2(2000),                                                                                                                                                                     
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                               
	 PRIMARY KEY ("EVENT_FOLLOW_ID")                                                                                                                                                                            
  USING INDEX  ENABLE,                                                                                                                                                                                       
	 CONSTRAINT "TENANTEVENTFOLLOWUSERS_EVENT_USER_UNIQUE" UNIQUE ("EVENT_ID", "EXT_USER_ID")                                                                                                                   
  USING INDEX  ENABLE                                                                                                                                                                                        
   ) ;                                                                                                                                                                                                       

